-- Задача 2: справочники NL_MATERIAL (материал дома) и NL_HOUSES (тип дома), связь с NL_PROP_RESALE

CREATE TABLE `NL_MATERIAL`  (
  `ID_NL_MATERIAL` int(11) NOT NULL AUTO_INCREMENT,
  `NL_MATERIAL_SHORT` varchar(25) NOT NULL,
  PRIMARY KEY (`ID_NL_MATERIAL`) USING BTREE
) ENGINE = InnoDB;

CREATE TABLE `NL_HOUSES`  (
  `ID_NL_HOUSES` int(11) NOT NULL AUTO_INCREMENT,
  `NL_HOUSES_SHORT` varchar(25) NOT NULL,
  `ID_NL_MATERIAL` int(11) NULL DEFAULT NULL,
  PRIMARY KEY (`ID_NL_HOUSES`) USING BTREE,
  INDEX `ID_NL_MATERIAL`(`ID_NL_MATERIAL`) USING BTREE,
  CONSTRAINT `nl_houses_ibfk_1` FOREIGN KEY (`ID_NL_MATERIAL`) REFERENCES `NL_MATERIAL` (`ID_NL_MATERIAL`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB;

ALTER TABLE `NL_PROP_RESALE`
  ADD COLUMN `ID_NL_HOUSES` int(11) NULL DEFAULT NULL AFTER `ID_NL_VIEW`,
  ADD COLUMN `ID_NL_MATERIAL` int(11) NULL DEFAULT NULL AFTER `ID_NL_HOUSES`,
  ADD INDEX `ID_NL_HOUSES`(`ID_NL_HOUSES`) USING BTREE,
  ADD INDEX `ID_NL_MATERIAL`(`ID_NL_MATERIAL`) USING BTREE,
  ADD CONSTRAINT `nl_prop_resale_ibfk_2` FOREIGN KEY (`ID_NL_HOUSES`) REFERENCES `NL_HOUSES` (`ID_NL_HOUSES`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  ADD CONSTRAINT `nl_prop_resale_ibfk_3` FOREIGN KEY (`ID_NL_MATERIAL`) REFERENCES `NL_MATERIAL` (`ID_NL_MATERIAL`) ON DELETE RESTRICT ON UPDATE RESTRICT;

